/* Builds the generated files of the extension. Run from anywhere: `npm run build:extension`.
   `--check` writes nothing and exits 1 when a committed file differs from what this builds.

   - pull.js: pull.entry.mjs bundled with core.mjs into one script (an injected file cannot import).
   - tokens.css: the light colours, then the dark set under prefers-color-scheme, both from
     shared/tokens.json, the one home of the palette (design-parchment-ledger).
   - badge-colors.mjs: the three badge fills and their text colour, from the same tokens. */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const dir = fileURLToPath(new URL(".", import.meta.url));
const tokens = JSON.parse(readFileSync(new URL("../shared/tokens.json", import.meta.url), "utf8"));
const HEADER = "Generated by extension/build.mjs. Do not edit.";

/* shared/tokens.json holds the light set under its plain names and the extension's dark set as
   darkPaper, darkCard and so on. The page follows prefers-color-scheme; the app stays light. */
const DARK = /^dark([A-Z].*)$/;
const light = Object.entries(tokens).filter(([k]) => !DARK.test(k));
const dark = Object.entries(tokens)
  .filter(([k]) => DARK.test(k))
  .map(([k, v]) => [k.replace(DARK, (_, rest) => rest[0].toLowerCase() + rest.slice(1)), v]);
const vars = (entries, indent = "") => entries.map(([k, v]) => `${indent}  --${k}: ${v};`).join("\n");

const bundle = await build({
  entryPoints: [`${dir}pull.entry.mjs`],
  bundle: true,
  format: "iife",
  globalName: "__ordersPull",
  footer: { js: "__ordersPull.run();" },
  target: "chrome110",
  legalComments: "none",
  write: false,
});

const files = {
  "pull.js": `/* ${HEADER} */\n${bundle.outputFiles[0].text}`,
  "tokens.css": `/* ${HEADER} */\n:root {\n${vars(light)}\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n${vars(dark, "  ")}\n  }\n}\n`,
  "badge-colors.mjs": `/* ${HEADER} */\n`
    + `export const BADGE_FILL = ${JSON.stringify({ success: tokens.accent, pulling: tokens.accent, "signed-out": tokens.amber, failure: tokens.red }, null, 2)};\n`
    + `export const BADGE_TEXT = ${JSON.stringify(tokens.card)};\n`,
};

const check = process.argv.includes("--check");
let stale = 0;
for (const [name, text] of Object.entries(files)) {
  let have = null;
  try {
    have = readFileSync(`${dir}${name}`, "utf8");
  } catch {}
  if (check) {
    if (have !== text) {
      stale++;
      console.error(`extension/${name} differs from its build`);
    }
  } else {
    writeFileSync(`${dir}${name}`, text);
    console.log(`wrote extension/${name}${have === text ? " (unchanged)" : ""}`);
  }
}
if (check) {
  if (stale) process.exit(1);
  console.log("extension build matches the committed files");
}
